15	package com.google.common.io;
16	
17	import static com.google.common.base.Preconditions.checkNotNull;
18	
19	import com.google.common.annotations.GwtIncompatible;
20	import com.google.common.annotations.J2ktIncompatible;
21	import com.google.errorprone.annotations.CanIgnoreReturnValue;
22	import java.io.BufferedOutputStream;
23	import java.io.IOException;
24	import java.io.InputStream;
25	import java.io.OutputStream;
26	import java.io.OutputStreamWriter;
27	import java.io.Writer;
28	import java.nio.charset.Charset;
29	
30	/**
31	 * A destination to which bytes can be written, such as a file. Unlike an {@link OutputStream}, a
32	 * {@code ByteSink} is not an open, stateful stream that can be written to and closed. Instead, it
33	 * is an immutable <i>supplier</i> of {@code OutputStream} instances.
34	 *
35	 * <p>{@code ByteSink} provides two kinds of methods:
36	 *
37	 * <ul>
38	 *   <li><b>Methods that return a stream:</b> These methods should return a <i>new</i>, independent
39	 *       instance each time they are called. The caller is responsible for ensuring that the
40	 *       returned stream is closed.
41	 *   <li><b>Convenience methods:</b> These are implementations of common operations that are
42	 *       typically implemented by opening a stream using one of the methods in the first category,
43	 *       doing something and finally closing the stream or channel that was opened.
44	 * </ul>
45	 *
46	 * @since 14.0
47	 * @author Colin Decker
48	 */
49	@J2ktIncompatible
50	@GwtIncompatible
51	public abstract class ByteSink {
52	
53	  /** Constructor for use by subclasses. */
54	  protected ByteSink() {}
55	
56	  /**
57	   * Returns a {@link CharSink} view of this {@code ByteSink} that writes characters to this sink as
58	   * bytes encoded with the given {@link Charset charset}.
59	   */
60	  public CharSink asCharSink(Charset charset) {
61	    return new AsCharSink(charset);
62	  }
63	
64	  /**
65	   * Opens a new {@link OutputStream} for writing to this sink. This method returns a new,
66	   * independent stream each time it is called.
67	   *
68	   * <p>The caller is responsible for ensuring that the returned stream is closed.
69	   *
70	   * @throws IOException if an I/O error occurs while opening the stream
71	   */
72	  public abstract OutputStream openStream() throws IOException;
73	
74	  /**
75	   * Opens a new buffered {@link OutputStream} for writing to this sink. The returned stream is not
76	   * required to be a {@link BufferedOutputStream} in order to allow implementations to simply
77	   * delegate to {@link #openStream()} when the stream returned by that method does not benefit from
78	   * additional buffering (for example, a {@code ByteArrayOutputStream}). This method returns a new,
79	   * independent stream each time it is called.
80	   *
81	   * <p>The caller is responsible for ensuring that the returned stream is closed.
82	   *
83	   * @throws IOException if an I/O error occurs while opening the stream
84	   * @since 15.0 (in 14.0 with return type {@link BufferedOutputStream})
85	   */
86	  public OutputStream openBufferedStream() throws IOException {
87	    OutputStream out = openStream();
88	    return (out instanceof BufferedOutputStream)
89	        ? (BufferedOutputStream) out
90	        : new BufferedOutputStream(out);
91	  }
92	
93	  /**
94	   * Writes all the given bytes to this sink.
95	   *
96	   * @throws IOException if an I/O occurs while writing to this sink
97	   */
98	  public void write(byte[] bytes) throws IOException {
99	    checkNotNull(bytes);
100	
101	    try (OutputStream out = openStream()) {
102	      out.write(bytes);
103	    }
104	  }
105	
106	  /**
107	   * Writes all the bytes from the given {@code InputStream} to this sink. Does not close {@code
108	   * input}.
109	   *
110	   * @return the number of bytes written
111	   * @throws IOException if an I/O occurs while reading from {@code input} or writing to this sink
112	   */
113	  @CanIgnoreReturnValue
114	  public long writeFrom(InputStream input) throws IOException {
115	    checkNotNull(input);
116	
117	    try (OutputStream out = openStream()) {
118	      return ByteStreams.copy(input, out);
119	    }
120	  }
121	
122	  /**
123	   * A char sink that encodes written characters with a charset and writes resulting bytes to this
124	   * byte sink.
125	   */
126	  private final class AsCharSink extends CharSink {
127	
128	    private final Charset charset;
